CREATE TABLE IF NOT EXISTS workflows(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,revision INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1))) STRICT;
CREATE TABLE IF NOT EXISTS workflow_versions(workflow TEXT NOT NULL REFERENCES workflows(id),revision INTEGER NOT NULL,graph TEXT NOT NULL,PRIMARY KEY(workflow,revision)) STRICT;
CREATE TABLE IF NOT EXISTS workflow_runs(id TEXT PRIMARY KEY,workflow TEXT NOT NULL REFERENCES workflows(id),version INTEGER NOT NULL,agent TEXT NOT NULL REFERENCES agents(id),graph TEXT NOT NULL,input TEXT NOT NULL,last TEXT NOT NULL,cursor TEXT NOT NULL,steps INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('ready','waiting','approval','done','failed','cancelled')),error TEXT,created TEXT NOT NULL,retry_settings TEXT) STRICT;
CREATE TABLE IF NOT EXISTS workflow_steps(run TEXT NOT NULL REFERENCES workflow_runs(id),seq INTEGER NOT NULL,node TEXT NOT NULL,turn TEXT UNIQUE REFERENCES turns(id),model TEXT,status TEXT NOT NULL CHECK(status IN('waiting','approval','done','failed','cancelled')),detail TEXT,settings TEXT,PRIMARY KEY(run,seq)) STRICT;
CREATE TABLE IF NOT EXISTS workflow_waits(run TEXT NOT NULL,seq INTEGER NOT NULL,event TEXT NOT NULL,secret_ref TEXT NOT NULL,secret_generation INTEGER NOT NULL,source_device_id TEXT NOT NULL REFERENCES devices(id),deadline INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('waiting','received','expired','closed')),delivery TEXT,digest TEXT,result TEXT,PRIMARY KEY(run,seq),FOREIGN KEY(run,seq) REFERENCES workflow_steps(run,seq)) STRICT;
CREATE TABLE IF NOT EXISTS project_workflow_notifications(seq INTEGER PRIMARY KEY AUTOINCREMENT,project TEXT NOT NULL REFERENCES projects(id),account TEXT NOT NULL REFERENCES accounts(id),run TEXT NOT NULL REFERENCES workflow_runs(id),name TEXT NOT NULL,created INTEGER NOT NULL,read INTEGER NOT NULL DEFAULT 0 CHECK(read IN(0,1)),UNIQUE(project,account,run)) STRICT;
CREATE INDEX IF NOT EXISTS project_workflow_notifications_reader ON project_workflow_notifications(project,account,seq);
CREATE TABLE IF NOT EXISTS routines(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,prompt TEXT NOT NULL,next_at INTEGER NOT NULL,interval_ms INTEGER,enabled INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,trigger TEXT NOT NULL DEFAULT 'schedule',observation_revision INTEGER NOT NULL DEFAULT 1 CHECK(observation_revision>0)) STRICT;
CREATE TABLE IF NOT EXISTS routine_flows(routine TEXT PRIMARY KEY REFERENCES routines(id),graph TEXT NOT NULL CHECK(json_valid(graph)),revision INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS routine_occurrences(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,routine TEXT NOT NULL REFERENCES routines(id),project TEXT NOT NULL REFERENCES projects(id),due_at INTEGER NOT NULL,schedule_revision INTEGER NOT NULL,initiator_account TEXT NOT NULL REFERENCES accounts(id),assignment_revision INTEGER NOT NULL CHECK(assignment_revision>0),authority_generation TEXT NOT NULL,home_device TEXT NOT NULL REFERENCES devices(id),zone TEXT NOT NULL,zone_revision INTEGER NOT NULL,missed_count INTEGER NOT NULL CHECK(missed_count>=0),state TEXT NOT NULL CHECK(state IN('pending','admitted','done','failed','blocked')),graph_json TEXT CHECK(graph_json IS NULL OR json_valid(graph_json)),task TEXT UNIQUE REFERENCES tasks(id),observation_revision INTEGER NOT NULL DEFAULT 1 CHECK(observation_revision>0),source TEXT NOT NULL DEFAULT 'schedule' CHECK(source IN('schedule','manual','webhook')),schedule_kind TEXT NOT NULL DEFAULT 'instant' CHECK(schedule_kind IN('instant','interval','once','cron'))) STRICT;
CREATE TABLE IF NOT EXISTS routine_steps(occurrence TEXT NOT NULL REFERENCES routine_occurrences(id),agent TEXT NOT NULL REFERENCES agents(id),turn TEXT UNIQUE REFERENCES turns(id),state TEXT NOT NULL CHECK(state IN('waiting','queued','done','failed','skipped')),result TEXT NOT NULL,PRIMARY KEY(occurrence,agent)) STRICT;
CREATE INDEX IF NOT EXISTS routine_occurrences_active ON routine_occurrences(state,routine);
CREATE UNIQUE INDEX IF NOT EXISTS routine_occurrences_schedule ON routine_occurrences(routine,schedule_revision,due_at) WHERE source='schedule';
CREATE TABLE IF NOT EXISTS routine_webhooks(routine TEXT PRIMARY KEY REFERENCES routines(id),revision INTEGER NOT NULL CHECK(revision>0),generation INTEGER NOT NULL CHECK(generation>0),secret_ref TEXT NOT NULL,filters TEXT NOT NULL CHECK(json_valid(filters))) STRICT;
CREATE TABLE IF NOT EXISTS routine_webhook_receipts(id TEXT PRIMARY KEY,routine TEXT NOT NULL REFERENCES routines(id),event_id TEXT NOT NULL,payload_digest TEXT NOT NULL CHECK(length(payload_digest)=64),received INTEGER NOT NULL,result TEXT NOT NULL CHECK(json_valid(result)),UNIQUE(routine,event_id)) STRICT;
CREATE TABLE IF NOT EXISTS routine_schedule_bindings(routine TEXT PRIMARY KEY REFERENCES routines(id),project TEXT NOT NULL REFERENCES projects(id),initiator_account TEXT NOT NULL REFERENCES accounts(id),assignment_revision INTEGER NOT NULL CHECK(assignment_revision>0),authority_generation TEXT NOT NULL,home_device TEXT NOT NULL REFERENCES devices(id),zone TEXT NOT NULL,zone_revision INTEGER NOT NULL CHECK(zone_revision>0),spec_json TEXT CHECK(spec_json IS NULL OR json_valid(spec_json))) STRICT;
CREATE TRIGGER IF NOT EXISTS routine_observation_revision AFTER UPDATE OF revision ON routines WHEN OLD.revision IS NOT NEW.revision BEGIN UPDATE routines SET observation_revision=OLD.observation_revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS routine_zone_observation_revision AFTER UPDATE OF zone,zone_revision ON routine_schedule_bindings WHEN OLD.zone IS NOT NEW.zone OR OLD.zone_revision IS NOT NEW.zone_revision BEGIN UPDATE routines SET observation_revision=observation_revision+1 WHERE id=NEW.routine; END;
CREATE TRIGGER IF NOT EXISTS routine_occurrence_observation_revision AFTER UPDATE OF task,state,missed_count ON routine_occurrences WHEN OLD.task IS NOT NEW.task OR OLD.state IS NOT NEW.state OR OLD.missed_count IS NOT NEW.missed_count BEGIN UPDATE routine_occurrences SET observation_revision=OLD.observation_revision+1 WHERE id=NEW.id; END;
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,project TEXT NOT NULL,agent TEXT NOT NULL,home_device TEXT NOT NULL REFERENCES devices(id),initiator_account TEXT NOT NULL REFERENCES accounts(id),assignment_revision INTEGER NOT NULL CHECK(assignment_revision>0),authority_generation TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('instant','once','interval','cron','legacy_interval')),zone TEXT NOT NULL,zone_revision INTEGER NOT NULL CHECK(zone_revision>0),spec_json TEXT NOT NULL CHECK(json_valid(spec_json)),next_at INTEGER,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),revision INTEGER NOT NULL CHECK(revision>0),observation_revision INTEGER NOT NULL DEFAULT 1 CHECK(observation_revision>0),FOREIGN KEY(project,agent) REFERENCES agent_projects(project,agent)) STRICT;
CREATE TABLE IF NOT EXISTS workflow_schedule_targets(schedule TEXT PRIMARY KEY REFERENCES schedules(id),workflow TEXT NOT NULL UNIQUE REFERENCES workflows(id),input TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS occurrences(schedule TEXT NOT NULL REFERENCES schedules(id),occurrence_id TEXT NOT NULL,due_at INTEGER NOT NULL,schedule_revision INTEGER NOT NULL,zone_revision INTEGER NOT NULL,initiator_account TEXT NOT NULL REFERENCES accounts(id),assignment_revision INTEGER NOT NULL CHECK(assignment_revision>0),authority_generation TEXT NOT NULL,task TEXT REFERENCES tasks(id),state TEXT NOT NULL CHECK(state IN('pending','admitted','consumed','blocked')),missed_count INTEGER NOT NULL CHECK(missed_count>=0),run TEXT UNIQUE REFERENCES workflow_runs(id),admission_id TEXT NOT NULL UNIQUE,observation_revision INTEGER NOT NULL DEFAULT 1 CHECK(observation_revision>0),PRIMARY KEY(schedule,occurrence_id)) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS occurrence_pending ON occurrences(schedule,schedule_revision) WHERE state IN('pending','blocked');
CREATE TRIGGER IF NOT EXISTS schedule_observation_revision AFTER UPDATE OF revision,zone,zone_revision,next_at,enabled ON schedules WHEN OLD.revision IS NOT NEW.revision OR OLD.zone IS NOT NEW.zone OR OLD.zone_revision IS NOT NEW.zone_revision OR OLD.next_at IS NOT NEW.next_at OR OLD.enabled IS NOT NEW.enabled BEGIN UPDATE schedules SET observation_revision=OLD.observation_revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS occurrence_observation_revision AFTER UPDATE OF state,missed_count,task,run ON occurrences WHEN OLD.state IS NOT NEW.state OR OLD.missed_count IS NOT NEW.missed_count OR OLD.task IS NOT NEW.task OR OLD.run IS NOT NEW.run BEGIN UPDATE occurrences SET observation_revision=OLD.observation_revision+1 WHERE schedule=NEW.schedule AND occurrence_id=NEW.occurrence_id; END;
CREATE TABLE IF NOT EXISTS routine_scheduler_cursors(kind TEXT PRIMARY KEY,after_id TEXT NOT NULL) STRICT;
INSERT OR IGNORE INTO routine_scheduler_cursors VALUES('schedule',''),('flow',''),('workflow_schedule','');
CREATE TABLE IF NOT EXISTS routine_cron_cursors(routine TEXT PRIMARY KEY REFERENCES routines(id),occurrence_id TEXT NOT NULL,counted_at INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS workflow_schedule_cron_cursors(schedule TEXT PRIMARY KEY REFERENCES schedules(id),occurrence_id TEXT NOT NULL,counted_at INTEGER NOT NULL) STRICT;
